workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who browses and buys books"

        bookshop = softwareSystem "Bookshop" "An online bookshop for buying books" {
            webStore = container "Web Store" "A web application for browsing the catalogue and placing orders" "Web"
            orderProcessor = container "Order Processor" "Processes and fulfils customer orders" "Service"
        }

        customer -> bookshop "Buys books from" "HTTPS"
        customer -> webStore "Browses the catalogue and places orders through" "HTTPS"
        webStore -> orderProcessor "Submits orders to" "gRPC"
    }

    views {
        systemContext bookshop "SystemContext" "The system context view of the Bookshop" {
            include *
            autoLayout
        }
        updateViews
    }
}

